#define D 1024
int matrix[D][D];

// Good Spatial Locality (Row-Major access in C/C++)
// Adjacent elements in memory are accessed sequentially.
void row_major_access() {
    for (int i = 0; i < D; i++)
        for (int j = 0; j < D; j++)
            matrix[i][j] += 1;
}

// Poor Spatial Locality (Column-Major access)
// Access pattern causes large jumps, requiring many cache line fetches.
void column_major_access() {
    for (int j = 0; j < D; j++)
        for (int i = 0; i < D; i++)
            matrix[i][j] += 1;
}
#define BLOCK 16
float data[1024];

// Temporal Locality: The register 'block_sum' is reused
// frequently before moving to the next block of data.
void exploit_temporal_locality() {
    float total_sum = 0.0;
    for (int i = 0; i < 1024; i += BLOCK) {
        float block_sum = 0.0;
        for (int j = 0; j < BLOCK; j++) {
            block_sum += data[i + j]; // Data[i+j] also exhibits spatial locality
        }
        total_sum += block_sum;
    }
}
// Cache-line aware programming: False Sharing avoidance

struct __attribute__((aligned(64))) PaddedCounter {
    long value;
    char padding[64 - sizeof(long)]; // Fill cache line (64 bytes common size)
};

// If 'value' lacked padding, concurrent updates to C1 and C2
// by different threads would compete for the same cache line (False Sharing).
PaddedCounter C1, C2;

// Accessing C1 and C2 simultaneously is efficient due to alignment/padding.
void parallel_safe_update() {
    C1.value++;
    C2.value++;
}
